using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json")]
    [Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "ConfigMcpServer",
            Version = "1.0.0",
            MaxConnections = 100,
            Features = new { CachingEnabled = true, DebugMode = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "API Endpoints",
        MimeType = "application/json")]
    [Description("Returns the list of configured API endpoints.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Name = "Users", Url = "https://api.example.com/users" },
            new { Name = "Products", Url = "https://api.example.com/products" }
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Validates whether a configuration key exists and returns its value.")]
    public static string ValidateConfigKey(
        [Description("The configuration key to look up (e.g., 'MaxConnections')")] string key)
    {
        var knownKeys = new Dictionary<string, string>
        {
            ["AppName"] = "ConfigMcpServer",
            ["Version"] = "1.0.0",
            ["MaxConnections"] = "100",
            ["CachingEnabled"] = "true",
            ["DebugMode"] = "false"
        };

        return knownKeys.TryGetValue(key, out var value)
            ? $"Key '{key}' = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", knownKeys.Keys)}";
    }
}

